use moloch_live_runtime::feedback;
#[path="../src/collateral_reconciliation.rs"] mod collateral_reconciliation;
use collateral_reconciliation::{Assessment,Snapshot,Plan,MoneyEvidence,WindowProvenance,Bounds};
use baal_transport_service::{Receipt,Scope,multi_leg::{Basket,Leg,Side}};
use serde_json::{Value,json};
const T:&str="11111111-1111-4111-8111-111111111111";
const PROFILE:&str="22222222-2222-4222-8222-222222222222";
fn iso(n:i64)->String{chrono::DateTime::from_timestamp_millis(1_792_022_400_000i64+n).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn r(endpoint:String,start:i64,end:i64,data:Value)->Receipt{Receipt{endpoint,status:200,request_started_at:iso(start),received_at:iso(end),data}}
fn available<T>(a:Assessment<T>)->T{match a{Assessment::Available(p)=>p,Assessment::Unavailable(reason)=>panic!("unexpected unavailable: {reason}")}}
fn component(advance:f64)->Value{json!({"profileId":PROFILE,"tournamentId":T,"componentId":"same-component","coveredExchangeIds":[101,102],"relationshipIds":[],"outstandingAdvance":advance,"guaranteedPayoutFloor":null,"diagnostic":null})}
struct Fixture{scope:Scope,basket:Basket,before_account:Receipt,before_collateral:Receipt,after_account:Receipt,after_collateral:Receipt,ack:Receipt,tapes:Vec<Receipt>}
impl Fixture{
 fn new()->Self{
  let scope=Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into()),("102".into(),"102".into())].into()};
  let basket=Basket{idempotency_key:"package-1".into(),tournament_id:T.into(),maximum_cost:"5.250000".into(),relationship_constraint:None,legs:vec![Leg{exchange_id:"101".into(),side:Side::No,quantity:5,limit_price:"0.600000".into()},Leg{exchange_id:"102".into(),side:Side::Yes,quantity:5,limit_price:"0.450000".into()}]};
  let before_account=r(format!("/account?tournamentId={T}"),0,10,json!({"id":PROFILE,"balance":100,"availableAdvance":0,"buyingPower":100}));let before_collateral=r(format!("/portfolio/collateral?tournamentId={T}"),20,30,json!({"availableAdvance":0,"data":[component(1.0)]}));
  let after_account=r(format!("/account?tournamentId={T}"),300,310,json!({"id":PROFILE,"balance":96.55,"availableAdvance":0,"buyingPower":96.55}));let after_collateral=r(format!("/portfolio/collateral?tournamentId={T}"),320,330,json!({"availableAdvance":0,"data":[component(1.8)]}));
  let mut results=Vec::new();let mut tapes=Vec::new();for i in 0..2{let no=i==0;let id=if no{"901"}else{"902"};let ex=if no{"101"}else{"102"};let side=if no{"no"}else{"yes"};let signed=if no{-5}else{5};let price=if no{0.6}else{0.45};let notional=if no{3.0}else{2.25};let effective=if no{2.5}else{1.75};let impact=if no{2.1}else{1.35};
   results.push(json!({"index":i,"data":{"orderId":id,"exchangeId":ex,"side":side,"action":"buy","quantity":5,"quantityTraded":signed,"remainingQuantity":0,"price":price,"fillPrice":price,"totalCost":notional,"open":false,"all":{"fullNotionalCost":notional,"effectiveEntryCost":effective,"collateralSavings":0.5,"relationshipIds":[],"componentId":"same-component","guaranteedPayoutFloorAfter":5,"outstandingAdvanceAfter":1.8,"collateralRepayment":0.1,"redemptionCredit":0.5,"netBuyingPowerImpact":impact}}}));
   tapes.push(r(format!("/orders/{id}/fills?limit=200&tournamentId={T}"),210+i*20,220+i*20,json!({"orderId":id,"exchangeId":ex,"tournamentId":T,"coverage":{"complete":true,"projectedThroughSequence":100},"pagination":{"hasMore":false,"nextCursor":null},"totalQuantityFilled":signed,"avgFillPrice":price,"data":[{"id":format!("80{i}"),"price":price,"quantity":signed,"side":side,"filledAt":iso(110+i*10)}]})));
  }
  let ack=r("/orders/multi-leg".into(),100,200,json!({"results":results}));Self{scope,basket,before_account,before_collateral,after_account,after_collateral,ack,tapes}
 }
 fn bounds()->Bounds{Bounds{maximum_snapshot_span_ms:1000,maximum_window_ms:5000}}
 fn provenance()->WindowProvenance{WindowProvenance{lease_sha256:"a".repeat(64),before_journal_sha256:"b".repeat(64),after_journal_sha256:"c".repeat(64)}}
 fn fees()->MoneyEvidence{available(MoneyEvidence::new(0,&"d".repeat(64),&iso(0),&iso(1)))}
 fn native()->MoneyEvidence{available(MoneyEvidence::new(1_000_000,&"e".repeat(64),&iso(220),&iso(250)))}
 fn run(&self)->Assessment<Plan>{let before=match Snapshot::observe(&self.scope,&self.before_account,&self.before_collateral,&Self::bounds()){Assessment::Available(v)=>v,Assessment::Unavailable(e)=>return Assessment::Unavailable(e)};let after=match Snapshot::observe(&self.scope,&self.after_account,&self.after_collateral,&Self::bounds()){Assessment::Available(v)=>v,Assessment::Unavailable(e)=>return Assessment::Unavailable(e)};collateral_reconciliation::reconcile(&self.scope,&before,&after,&self.basket,&self.ack,&self.tapes,Some(&Self::fees()),Some(&Self::native()),&Self::provenance(),&Self::bounds())}
}
#[test]fn repeated_component_after_is_state_not_two_advances_and_native_redemption_not_recredited(){let f=Fixture::new();let p=available(f.run());let a=p.aggregate();assert_eq!(a["grossPositionCost"],5_250_000);assert_eq!(a["advanceDrawnConsistent"],1_000_000);assert_eq!(a["advanceDelta"],800_000);assert_eq!(a["repayment"],200_000);assert_eq!(a["redemption"],1_000_000);assert_eq!(a["netCashAdjustment"],800_000);assert_eq!(a["actualCashDelta"],-3_450_000);assert_eq!(a["netWealthExAdvance"],-4_250_000);assert_eq!(a["componentAfterStateCount"],1);assert_eq!(a["atomicAccountBarrier"],false);assert!(a.get("profileId").is_none());assert_eq!(p.private_evidence()["originalMultiLegReceiptHash"],feedback::digest(&f.ack).unwrap());}
#[test]fn canonical_order_tape_duplicate_counts_once_changed_lifecycle_does_not(){let mut f=Fixture::new();let mut duplicate=f.tapes[0].clone();duplicate.request_started_at=iso(250);duplicate.received_at=iso(260);f.tapes.push(duplicate);let p=available(f.run());assert_eq!(p.aggregate()["actualFillCount"],2);assert_eq!(p.aggregate()["canonicalOrderCount"],2);f.tapes[2].data["data"][0]["price"]=json!(0.55);assert_eq!(f.run().reason(),Some("CHANGED_CUMULATIVE_TAPE"));}
#[test]fn full_ack_without_actual_tapes_or_inconsistent_notional_never_counts_fills(){let mut f=Fixture::new();f.tapes.clear();assert_eq!(f.run().reason(),Some("FILL_TAPE_COUNT"));let mut f=Fixture::new();f.tapes[0].data["data"][0]["price"]=json!(0.55);assert_eq!(f.run().reason(),Some("ACTUAL_NOTIONAL_OR_QUANTITY_MISMATCH"));let mut f=Fixture::new();f.tapes[0].data["coverage"]["complete"]=json!(false);assert_eq!(f.run().reason(),Some("FILL_TAPE_INVALID"));}
#[test]fn null_cash_all_or_missing_independent_fees_are_unavailable(){let mut f=Fixture::new();f.before_account.data["balance"]=Value::Null;f.before_account.data["buyingPower"]=Value::Null;assert_eq!(f.run().reason(),Some("CASH_UNAVAILABLE"));let mut f=Fixture::new();f.ack.data["results"][0]["data"]["all"]=Value::Null;assert_eq!(f.run().reason(),Some("ALL_ECONOMICS_UNAVAILABLE"));let f=Fixture::new();let before=available(Snapshot::observe(&f.scope,&f.before_account,&f.before_collateral,&Fixture::bounds()));let after=available(Snapshot::observe(&f.scope,&f.after_account,&f.after_collateral,&Fixture::bounds()));assert_eq!(collateral_reconciliation::reconcile(&f.scope,&before,&after,&f.basket,&f.ack,&f.tapes,None,Some(&Fixture::native()),&Fixture::provenance(),&Fixture::bounds()).reason(),Some("FEES_UNAVAILABLE"));assert!(MoneyEvidence::new(-1,&"a".repeat(64),&iso(0),&iso(1)).reason().is_some());}
#[test]fn cash_debt_and_buying_power_differences_are_checked_separately(){let mut f=Fixture::new();f.after_collateral.data["data"][0]["outstandingAdvance"]=json!(1.9);for row in f.ack.data["results"].as_array_mut().unwrap(){row["data"]["all"]["outstandingAdvanceAfter"]=json!(1.9);}assert_eq!(f.run().reason(),Some("LIABILITY_FLOW_MISMATCH"));let mut f=Fixture::new();f.after_account.data["balance"]=json!(97);f.after_account.data["buyingPower"]=json!(97);assert_eq!(f.run().reason(),Some("CASH_FLOW_MISMATCH"));let mut f=Fixture::new();f.ack.data["results"][0]["data"]["all"]["netBuyingPowerImpact"]=json!(0);assert_eq!(f.run().reason(),Some("BUYING_POWER_FLOW_MISMATCH"));}
#[test]fn scope_profile_clock_and_ambiguous_component_after_are_never_guessed(){let mut f=Fixture::new();f.after_collateral.data["data"][0]["profileId"]=json!("33333333-3333-4333-8333-333333333333");assert_eq!(f.run().reason(),Some("COLLATERAL_PROFILE_SCOPE"));let mut f=Fixture::new();f.after_account.endpoint="/account".into();assert_eq!(f.run().reason(),Some("RECEIPT_SCOPE_OR_STATUS"));let mut f=Fixture::new();f.tapes[0].received_at=iso(301);assert_eq!(f.run().reason(),Some("FILL_OBSERVATION_WINDOW"));let mut f=Fixture::new();f.ack.data["results"][1]["data"]["all"]["outstandingAdvanceAfter"]=json!(1.7);assert_eq!(f.run().reason(),Some("AMBIGUOUS_COMPONENT_AFTER_ORDER"));let mut f=Fixture::new();f.after_collateral.data["data"][0]["outstandingAdvance"]=json!(-1);assert_eq!(f.run().reason(),Some("COLLATERAL_INVALID"));}
#[test]fn cross_component_lending_reconciles_account_debt_without_using_own_after_as_delta(){let mut f=Fixture::new();for row in f.ack.data["results"].as_array_mut().unwrap(){row["data"]["all"]["componentId"]=Value::Null;row["data"]["all"]["outstandingAdvanceAfter"]=json!(0);}let p=available(f.run());assert_eq!(p.aggregate()["componentAfterStateCount"],0);assert_eq!(p.aggregate()["advanceDelta"],800_000);assert_eq!(p.aggregate()["advanceDrawnConsistent"],1_000_000);}
